import { ReactElement } from 'react';

import { StoryFn } from '@storybook/react';

import { Chart } from '../../Chart.js';
import { Axis, ChartInspect, Legend, Scatter } from '../../components/index.js';
import useChartProps from '../../hooks/useChartProps.js';
import { bindWithProps } from '../../test-utils/index.js';
import { ScatterProps } from '../../types/index.js';
import { campaignPerformanceData } from './scatterData.js';

export default {
  title: 'React Spectrum Charts 2/Scatter/Examples',
  tags: ['alpha'],
  component: Scatter,
};

const CampaignPerformanceStory: StoryFn<ScatterProps> = (args): ReactElement => {
  const chartProps = useChartProps({ data: campaignPerformanceData, width: 640, height: 420, idKey: 'id' });
  return (
    <Chart {...chartProps}>
      <Axis position="bottom" grid ticks baseline title="Spend ($K)" />
      <Axis position="left" grid title="Revenue ($K)" />
      <Scatter {...args}>
        <ChartInspect>
          {(datum) => (
            <div>
              <strong>{String(datum.campaign)}</strong>
              <div>Spend: ${String(datum.spend)}K</div>
              <div>Revenue: ${String(datum.revenue)}K</div>
              <div>Conversions: {Number(datum.conversions).toLocaleString()}</div>
            </div>
          )}
        </ChartInspect>
      </Scatter>
      <Legend title="Channel" position="right" highlight />
    </Chart>
  );
};

const CampaignPerformance = bindWithProps(CampaignPerformanceStory);
CampaignPerformance.args = { dimension: 'spend', metric: 'revenue', color: 'channel' };
Object.assign(CampaignPerformance, { parameters: { controls: { include: [] } } });

export { CampaignPerformance };
